<template><div v-if="b" class="rounded bg-white p-8 shadow"><h1 class="text-3xl font-bold">{{b.title}}</h1><p class="mt-2 text-sm text-slate-500">{{b.writerName}}</p><article class="my-8 whitespace-pre-wrap">{{b.content}}</article><div class="flex gap-2"><RouterLink :to="`/admin/boards/${b.id}/edit`" class="rounded bg-slate-900 px-4 py-2 text-white">수정</RouterLink><button @click="remove" class="rounded border px-4 py-2">삭제</button><RouterLink to="/admin/boards" class="rounded border px-4 py-2">목록</RouterLink></div></div></template>
<script setup>import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{adminApi}from'../../api/adminApi';const route=useRoute(),router=useRouter(),b=ref(null);onMounted(async()=>b.value=(await adminApi.board(route.params.id)).data);async function remove(){if(confirm('삭제할까요?')){await adminApi.deleteBoard(route.params.id);router.push('/admin/boards')}}</script>